export const EARTH_RADIUS_KM = 6371;
export const OBSERVER_HEIGHT_METERS = 1.7;
export const REFRACTION_K_STANDARD = 7 / 6;
export const effectiveRadiusKm = (k = REFRACTION_K_STANDARD) => EARTH_RADIUS_KM * k;
export function horizonDistanceKm(elevMeters, cloudMeters, k = REFRACTION_K_STANDARD) {
    const re = effectiveRadiusKm(k);
    const hObsKm = (elevMeters + OBSERVER_HEIGHT_METERS) / 1000;
    const hCloudKm = cloudMeters / 1000;
    return (Math.sqrt(2 * re * hObsKm + hObsKm * hObsKm) +
        Math.sqrt(2 * re * hCloudKm + hCloudKm * hCloudKm));
}
export function horizonDipRad(elevMeters, k = REFRACTION_K_STANDARD) {
    const re = effectiveRadiusKm(k);
    const rObs = re + (elevMeters + OBSERVER_HEIGHT_METERS) / 1000;
    if (!(rObs > re))
        return 0;
    return Math.acos(re / rObs);
}
export function apparentAltitudeRad(trueAltitudeRad) {
    const hDeg = (trueAltitudeRad * 180) / Math.PI;
    if (hDeg < -2)
        return trueAltitudeRad;
    const refractionArcmin = 1.02 / Math.tan(((hDeg + 10.3 / (hDeg + 5.11)) * Math.PI) / 180);
    return trueAltitudeRad + ((refractionArcmin / 60) * Math.PI) / 180;
}
export function blockDistanceKm(elevMeters, cloudMeters, apparentAltRad, k = REFRACTION_K_STANDARD) {
    if (!Number.isFinite(apparentAltRad))
        return null;
    if (apparentAltRad < -horizonDipRad(elevMeters, k))
        return null;
    const re = effectiveRadiusKm(k);
    const rObs = re + (elevMeters + OBSERVER_HEIGHT_METERS) / 1000;
    const rCloud = re + cloudMeters / 1000;
    if (!(rCloud > rObs))
        return null;
    const sinAlt = Math.sin(apparentAltRad);
    const b = 2 * rObs * sinAlt;
    const c = rObs * rObs - rCloud * rCloud;
    const disc = b * b - 4 * c;
    if (!(disc >= 0))
        return null;
    const t = (-b + Math.sqrt(disc)) / 2;
    if (!(t > 0))
        return null;
    const up = rObs + t * sinAlt;
    const horiz = t * Math.cos(apparentAltRad);
    const distKm = Math.atan2(horiz, up) * re;
    return Number.isFinite(distKm) ? distKm : null;
}
export function computeEndPoint(lat, lon, azimuthDeg, distanceKm) {
    const bearing = (azimuthDeg * Math.PI) / 180;
    const lat1 = (lat * Math.PI) / 180;
    const lon1 = (lon * Math.PI) / 180;
    const angDist = distanceKm / EARTH_RADIUS_KM;
    const lat2 = Math.asin(Math.sin(lat1) * Math.cos(angDist) +
        Math.cos(lat1) * Math.sin(angDist) * Math.cos(bearing));
    const lon2 = lon1 +
        Math.atan2(Math.sin(bearing) * Math.sin(angDist) * Math.cos(lat1), Math.cos(angDist) - Math.sin(lat1) * Math.sin(lat2));
    return [(lat2 * 180) / Math.PI, (lon2 * 180) / Math.PI];
}
